import { ChemicalRecord, PsiParameters, ProcessProject, DocumentRecord } from '../types';

export function exportProjectToJson(
  project: ProcessProject,
  documents: DocumentRecord[],
  chemicals: ChemicalRecord[],
  conflicts: any[],
  graph: any
): string {
  const exportPayload = {
    export_metadata: {
      generated_at: new Date().toISOString(),
      standard: 'OSHA 29 CFR 1910.119(d)(1) Process Safety Information',
      notice:
        'DISCLAIMER: This Process Safety Information (PSI) record is generated by an automated extraction and human evidence-management platform. It is NOT a certified safety assessment or risk-rating engine. Qualified process-safety professionals must independently review and verify all data before relying on it for engineering decisions.',
      project_id: project.id,
      project_name: project.name,
      is_sample: project.is_sample,
    },
    project,
    documents: documents.map((d) => ({
      id: d.id,
      name: d.name,
      type: d.doc_type,
      size_bytes: d.size_bytes,
      pages_count: d.pages_count,
      is_readable: d.is_readable,
      unreadable_reason: d.unreadable_reason,
      upload_timestamp: d.upload_timestamp,
    })),
    chemicals: chemicals.map((c) => ({
      id: c.id,
      chemical_name: c.chemical_name,
      cas_number: c.cas_number,
      sds_revision_date: c.sds_revision_date,
      manufacturer: c.manufacturer,
      psi_parameters: c.psi_parameters,
      created_at: c.created_at,
      updated_at: c.updated_at,
    })),
    conflicts,
    process_topology: graph,
  };

  return JSON.stringify(exportPayload, null, 2);
}

function escapeCsvCell(cell: any): string {
  if (cell === null || cell === undefined) return '""';
  const str = String(cell);
  const escaped = str.replace(/"/g, '""');
  return `"${escaped}"`;
}

export function exportProjectToCsv(chemicals: ChemicalRecord[]): string {
  const headers = [
    'Chemical Name',
    'CAS Number',
    'Manufacturer',
    'SDS Revision Date',
    'PSI Parameter Key',
    'PSI Parameter Name',
    'Effective Value',
    'Machine Extracted Value',
    'User Confirmed Value',
    'Review Status',
    'Confidence Score',
    'Source Document',
    'Source Page',
    'Source Section',
    'Verbatim Evidence Snippet',
    'Reviewer Notes',
    'Last Updated',
  ];

  const rows: string[] = [headers.map(escapeCsvCell).join(',')];

  const psiKeys: { key: keyof PsiParameters; label: string }[] = [
    { key: 'toxicity', label: 'Toxicity Information' },
    { key: 'permissible_exposure_limits', label: 'Permissible Exposure Limits (PEL/TLV)' },
    { key: 'physical_data', label: 'Physical Data' },
    { key: 'reactivity_data', label: 'Reactivity Data' },
    { key: 'corrosivity_data', label: 'Corrosivity Data' },
    { key: 'thermal_and_chemical_stability_data', label: 'Thermal & Chemical Stability Data' },
    { key: 'inadvertent_mixing_hazards', label: 'Hazardous Effects of Inadvertent Mixing' },
  ];

  for (const chem of chemicals) {
    const chemName = chem.chemical_name.user_value || chem.chemical_name.value || 'Unknown';
    const casNum = chem.cas_number.user_value || chem.cas_number.value || 'Unknown';
    const mfr = chem.manufacturer.user_value || chem.manufacturer.value || 'N/A';
    const revDate = chem.sds_revision_date.user_value || chem.sds_revision_date.value || 'N/A';

    for (const { key, label } of psiKeys) {
      const field = chem.psi_parameters[key];
      const effectiveVal = field.user_value !== null ? field.user_value : field.value;

      const row = [
        chemName,
        casNum,
        mfr,
        revDate,
        key,
        label,
        effectiveVal || '(Missing / Not Provided)',
        field.machine_value || '(None)',
        field.user_value || '(Unchanged)',
        field.review_status,
        `${Math.round((field.confidence || 0) * 100)}%`,
        field.source.document || 'N/A',
        field.source.page !== null ? String(field.source.page) : 'N/A',
        field.source.section || 'N/A',
        field.source.snippet || field.missing_reason || 'N/A',
        field.notes || '',
        field.updated_at || chem.updated_at,
      ];

      rows.push(row.map(escapeCsvCell).join(','));
    }
  }

  return rows.join('\r\n');
}
